/* file : DTModelMapper.xml, id : getDTModelList */ SELECT * FROM ( SELECT A.* , (SELECT DTL_CD_NM FROM TB_CODE_DTL T WHERE T.DEL_YN = 'N' AND T.GRP_CD = 'STATUS' AND T.DTL_CD = A.MODEL_STATUS) STATUS_NM , (SELECT USER_ID FROM TB_USER U WHERE U.DEL_YN = 'N' AND U.USER_SEQ = A.REG_USER_SEQ) USER_ID FROM TB_META_MODEL A WHERE A.DEL_YN = 'N' AND A.USE_YN = 'Y' ) TB
WHERE MODEL_NM LIKE CONCAT('%', #{keyword}, '%')
ORDER BY REG_DT DESC /*||ORDER BY REG_DT DESC||*/

/* file : DTModelMapper.xml, id : getDTModelList */ SELECT * FROM ( SELECT A.* , (SELECT DTL_CD_NM FROM TB_CODE_DTL T WHERE T.DEL_YN = 'N' AND T.GRP_CD = 'STATUS' AND T.DTL_CD = A.MODEL_STATUS) STATUS_NM , (SELECT USER_ID FROM TB_USER U WHERE U.DEL_YN = 'N' AND U.USER_SEQ = A.REG_USER_SEQ) USER_ID FROM TB_META_MODEL A WHERE A.DEL_YN = 'N' AND A.USE_YN = 'Y' ) TB WHERE JOB_LEVEL = #{job_level}
AND MODEL_NM LIKE CONCAT('%', #{keyword}, '%')
ORDER BY REG_DT DESC /*||ORDER BY REG_DT DESC||*/

