/* file : AugmentModelMapper.xml, id : getAugmentModel */
SELECT *, (SELECT FILE_PATH FROM TB_META_MODEL_FILES WHERE MODEL_SEQ = #{modelSeq} LIMIT 1) FILE_PATH
FROM TB_META_MODEL A
WHERE A.DEL_YN = 'N'
  AND A.USE_YN = 'Y'
  AND A.MODEL_SEQ = #{modelSeq}

/* file : DTModelMapper.xml, id : getDTModelListSetUserSeq */ SELECT * FROM ( SELECT A.* , (SELECT DTL_CD_NM FROM TB_CODE_DTL T WHERE T.DEL_YN = 'N' AND T.GRP_CD = 'STATUS' AND T.DTL_CD = A.MODEL_STATUS) STATUS_NM , (SELECT USER_ID FROM TB_USER U WHERE U.DEL_YN = 'N' AND U.USER_SEQ = A.REG_USER_SEQ) USER_ID FROM TB_META_MODEL A WHERE A.DEL_YN = 'N' AND A.USE_YN = 'Y' AND A.REG_USER_SEQ = #{user_seq} ) TB
WHERE MODEL_NM LIKE CONCAT('%', #{keyword}, '%')
/*||ORDER BY REG_DT DESC||*/

/* file : DTModelMapper.xml, id : getDTModelListSetUserSeq */
SELECT *
FROM (
SELECT A.*
, (SELECT DTL_CD_NM FROM TB_CODE_DTL T WHERE T.DEL_YN = 'N' AND T.GRP_CD = 'STATUS' AND T.DTL_CD =
A.MODEL_STATUS) STATUS_NM
, (SELECT USER_ID FROM TB_USER U WHERE U.DEL_YN = 'N' AND U.USER_SEQ = A.REG_USER_SEQ) USER_ID
FROM TB_META_MODEL A
WHERE A.DEL_YN = 'N'
AND A.USE_YN = 'Y'
AND A.REG_USER_SEQ = #{user_seq}
) TB WHERE JOB_LEVEL = #{job_level}

    AND MODEL_NM LIKE CONCAT('%', #{keyword}, '%')

/*||ORDER BY REG_DT DESC||*/

/* file : DTModelMapper.xml, id : getDTModelSharedList */ SELECT * FROM ( SELECT A.* , (SELECT DTL_CD_NM FROM TB_CODE_DTL T WHERE T.DEL_YN = 'N' AND T.GRP_CD = 'STATUS' AND T.DTL_CD = A.MODEL_STATUS) STATUS_NM , (SELECT USER_ID FROM TB_USER U WHERE U.DEL_YN = 'N' AND U.USER_SEQ = A.REG_USER_SEQ) USER_ID FROM TB_META_MODEL A WHERE A.DEL_YN = 'N' AND A.USE_YN = 'Y' AND A.RLS_YN = 'Y' AND A.MODEL_STATUS = 'DONE' ) TB
WHERE MODEL_NM LIKE CONCAT('%', #{keyword}, '%')
ORDER BY REG_DT DESC

/* file : DTModelMapper.xml, id : getDTModelSharedList */ SELECT * FROM ( SELECT A.* , (SELECT DTL_CD_NM FROM TB_CODE_DTL T WHERE T.DEL_YN = 'N' AND T.GRP_CD = 'STATUS' AND T.DTL_CD = A.MODEL_STATUS) STATUS_NM , (SELECT USER_ID FROM TB_USER U WHERE U.DEL_YN = 'N' AND U.USER_SEQ = A.REG_USER_SEQ) USER_ID FROM TB_META_MODEL A WHERE A.DEL_YN = 'N' AND A.USE_YN = 'Y' AND A.RLS_YN = 'Y' AND A.MODEL_STATUS = 'DONE' ) TB WHERE JOB_LEVEL = #{job_level}
AND MODEL_NM LIKE CONCAT('%', #{keyword}, '%')
ORDER BY REG_DT DESC

/* file : DTModelMapper.xml, id : getUnitFormula */
