/* file : DTModelMapper.xml, id : saveAlgorithmModelParams */
INSERT
INTO TB_META_MODEL_PARAMS ( MODEL_PARAMS_SEQ
                          , MODEL_SEQ
                          , MODEL_ALGRM_SEQ
                          , MODEL_PARAMS_ITEM_SEQ
                          , MODEL_PARAMS_ITEM_VALUE)
VALUES ( #{modelParamsSeq}
       , #{modelSeq}
       , #{modelAlgrmSeq}
       , #{modelParamsItemSeq}
       , #{modelParamsItemValue})

/* file : DTModelMapper.xml, id : saveAlgorithmModelColumn */
INSERT
INTO TB_META_MODEL_COLUMN ( MODEL_COL_SEQ
                          , MODEL_SEQ
                          , MODEL_COL_TP
                          , MODEL_COL_NM)
VALUES ( #{modelColSeq}
       , #{modelSeq}
       , #{modelColTp}
       , #{modelColNm})

mapper.update:
/* file : DTModelMapper.xml, id : updateAlgorithmSeq */
UPDATE TB_META_MODEL
SET MODEL_ALGRM_SEQ = #{algorithm_seq}
  , MDFCN_USER_SEQ  = #{reg_user_seq}
  , MDFCN_DT        = CURRENT_TIMESTAMP
  , MDFCN_IP        = #{reg_ip}
  , MODEL_STATUS    = 'WAIT'
  , JOB_LEVEL       = 'M'
WHERE MODEL_SEQ = #{model_seq}

/* file : DTModelMapper.xml, id : updateMetaUerItemFulltext */
UPDATE TB_META_USER_ITEM
SET USER_PPRCS_FULL_STNG_VALUE = #{user_pprcs_full_stng_value}
WHERE MODEL_SEQ = #{model_seq}

mapper.insert:
/* file : DTModelMapper.xml, id : insertModelFileInfo */
INSERT
INTO TB_META_MODEL_FILES (
FILE_SEQ
, MODEL_SEQ
, REF_TP
, FILE_NM
, FILE_PATH
, FILE_EXTN
, FILE_SZ
, REG_USER_SEQ
, REG_IP
)
VALUES (
#{fileSeq}
, #{model_seq}
, #{ref_tp}
, #{file_nm}
, #{file_path}
, #{file_extn}
, #{file_size}
, #{reg_user_seq}
, #{reg_ip}
)

    SELECT LAST_INSERT_ID()

mapper.update:
/* file : DTModelMapper.xml, id : updateModelFileInfo */
UPDATE TB_META_MODEL_FILES
SET FILE_NM        = #{file_nm}
  , FILE_PATH      = #{file_path}
  , FILE_EXTN      = #{file_extn}
  , FILE_SZ        = #{file_size}
  , MDFCN_USER_SEQ = #{reg_user_seq}
  , MDFCN_DT       = CURRENT_TIMESTAMP
  , MDFCN_IP       = #{reg_ip}
WHERE MODEL_SEQ = #{model_seq}
  AND REF_TP = #{ref_tp}

mapper.select:
/* file : DTModelMapper.xml, id : getCountModelFileInfo */
SELECT COUNT(*)
FROM TB_META_MODEL_FILES A
         JOIN TB_META_MODEL B ON A.MODEL_SEQ = B.MODEL_SEQ AND B.DEL_YN = 'N' AND B.USE_YN = 'Y'
    AND A.DEL_YN = 'N'
    AND A.MODEL_SEQ = B.MODEL_SEQ
    AND B.MODEL_SEQ = #{model_seq}
    AND A.REF_TP = #{ref_tp}

